import sys
from collections import defaultdict

def main():
    total_per_customer = defaultdict(float)
    with open('data/invoices.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            customer = row['customer']
            amount = float(row['amount'])
            total_per_customer[customer] += amount

    print("Total amount billed per customer:")
    for customer, total in sorted(total_per_customer.items()):
        print(f"{customer}: {total:.2f}")

if __name__ == '__main__':
    main()"}

